import type { FrameAnalysis } from '../enhance/enhanceModel';

export type OpType =
  | 'grade' | 'restore' | 'stabilize' | 'speed' | 'trim' | 'cut_silences' | 'captions' | 'reframe'
  | 'text' | 'motion_fx' | 'broll' | 'music' | 'audio_cleanup'
  | 'remove_bg' | 'replace_bg' | 'isolate' | 'restyle' | 'omni_effect';

/**
 * compose — folded into the final render request.
 * stage   — produces a new working source that later steps build on.
 * omni    — a stage generated by Omni Flash in ≤8s chunks (paid).
 * export  — a separate deliverable (transparent cut-out).
 */
export type Engine = 'compose' | 'stage' | 'omni' | 'export';

export type StepStatus = 'pending' | 'running' | 'done' | 'error' | 'awaiting' | 'skipped';

export type BillingState = 'none' | 'charged' | 'refunded' | 'refund_pending';
export interface Billing { entryKey: string | null; credits: number; state: BillingState }

export type ChunkStatus = 'pending' | 'trimming' | 'submitting' | 'generating' | 'done' | 'error';
export interface OmniChunk {
  index: number;
  start: number;
  end: number;
  status: ChunkStatus;
  trimUrl: string | null;
  operationId: string | null;
  outputUrl: string | null;
  outputDuration: number | null;
  billing: Billing;
  error: string | null;
  attempts: number;
  startedAt: number | null;
}

export interface MediaRef { url: string; width: number; height: number; duration: number }

export interface StepResult {
  /** Stage output, b-roll clip, generated background or cut-out. */
  url?: string;
  media?: MediaRef;
  /** The working-source URL this result was computed from; a change re-runs the step. */
  inputUrl?: string;
  keep?: { start: number; end: number }[];
  removedSeconds?: number;
  words?: TimedWord[];
  focus?: { t: number; x: number; y: number }[];
  shake?: { t: number; dx: number; dy: number }[];
  margin?: number;
  chromaColor?: string;
  route?: 'chroma' | 'omni' | 'export';
  stitchOperationId?: string | null;
  stitchGeometry?: string | null;
  summary?: string;
}

export interface Step {
  id: string;
  type: OpType;
  params: Record<string, any>;
  label: string;
  why: string;
  enabled: boolean;
  status: StepStatus;
  engine: Engine;
  detail: string;
  error: string | null;
  progress: number | null;
  estimate: number;
  billing: Billing;
  result: StepResult | null;
  chunks: OmniChunk[] | null;
  supersededBy: string | null;
  turnId: string | null;
  createdAt: number;
  updatedAt: number;
}

export interface TimedWord { text: string; start: number; end: number }

export type MessageRole = 'user' | 'agent' | 'system';
export interface ChatMessage {
  id: string;
  role: MessageRole;
  text: string;
  at: number;
  stepIds?: string[];
  model?: string;
  estimate?: number;
  tone?: 'info' | 'good' | 'bad';
  awaitingApproval?: boolean;
}

export interface RenderState {
  status: 'idle' | 'rendering' | 'done' | 'error';
  stage: string;
  hash: string | null;
  operationId: string | null;
  geometry: string | null;
  url: string | null;
  error: string | null;
  billing: Billing;
  startedAt: number | null;
  output: MediaRef | null;
  aspect: string | null;
}

export interface ExportRecord {
  id: string;
  kind: 'mp4' | 'cutout';
  url: string;
  createdAt: number;
  label: string;
  width: number;
  height: number;
  duration: number;
  hash: string | null;
  steps: string[];
}

export interface AgentSource {
  name: string;
  bytes: number;
  width: number;
  height: number;
  duration: number;
  url: string | null;
  poster: string | null;
  upload: { state: 'idle' | 'uploading' | 'done' | 'error'; progress: number };
  greenScreen: string | null;
  checkedKey: boolean;
}

export interface AgentProject {
  id: string;
  rowId: number | null;
  title: string;
  createdAt: number;
  updatedAt: number;
  source: AgentSource;
  analysis: FrameAnalysis | null;
  steps: Step[];
  messages: ChatMessage[];
  render: RenderState;
  exports: ExportRecord[];
  creditCap: number;
  /** Set when the user approved paid work above the cap for the current turn. */
  approvedCredits: number;
  phase: 'idle' | 'planning' | 'running' | 'rendering' | 'awaiting' | 'error' | 'done';
  error: string | null;
}

export interface PlannedStep { type: OpType; params: Record<string, any>; why: string }
export interface AgentPlan { reply: string; steps: PlannedStep[]; undo: string[]; model: string }
